import type {Document} from '@contentful/rich-text-types'
import type {ContentSchema} from '../lib/types/contentful/content-schema'

// By default, we will not include steps.
// If a content author has added steps in Contentful, we'll display those steps.
export const FindStaticSteps = (contentEntries: ContentSchema[]): Document | null => {
  const findEntry = contentEntries.find(entry => entry.fields.htmlId === 'signup-steps')
  return findEntry ? findEntry.fields?.text : null
}
