import {BulletStyle} from '../lib/types/bullet-style'
import type {ContentSchema} from '../lib/types/contentful/content-schema'

// By default, bullet style will be 'default': https://primer.style/brand/components/UnorderedList/react#default
// If a content author has opted for bullet-style-checked in Contentful, we'll display the checked style: https://primer.style/brand/components/UnorderedList/react#checked-variant
// Additionally, if the user is logged in, we show checked style to indicate completed steps
export const FindBulletStyle = (contentEntries: ContentSchema[], isLoggedIn?: boolean): BulletStyle => {
  // If user is logged in, show checked style (indicates "Create an account" step is complete)
  if (isLoggedIn) {
    return BulletStyle.checked
  }

  // Fall back to Contentful-driven bullet style
  const findEntry = contentEntries.find(entry => entry.fields.htmlId === 'bullet-style-checked')
  return findEntry ? BulletStyle.checked : BulletStyle.default
}
