import {Heading, Label, ThemeProvider} from '@primer/react-brand'
import {ContentfulContentBlock} from './components/ContentfulContentBlock'
import {FindBulletStyle} from './helpers/find-bullet-style'
import {FindLabelText} from './helpers/find-label-text'
import {FindStaticSteps} from './helpers/find-static-steps'
import {StaticSignupSteps} from './components/StaticSignupSteps'
import type {Document} from '@contentful/rich-text-types'
import type {ContentSchema} from './lib/types/contentful/content-schema'
import type {EntrySchema} from './lib/types/contentful/entry-schema'

import css from './CustomSignupContent.module.css'

export interface CustomSignupContentProps {
  contentfulContent: {
    entry: EntrySchema
    content_entries: ContentSchema[]
    assets: string[]
  }
  isLoggedIn?: boolean
}

export function CustomSignupContent({contentfulContent, isLoggedIn = false}: CustomSignupContentProps) {
  const title = contentfulContent.entry.fields.heading
  const text = contentfulContent.entry.fields.text
  const termsAndConditionsSubtext = contentfulContent.entry.fields.subheading
  const bulletStyle = FindBulletStyle(contentfulContent.content_entries, isLoggedIn)
  const labelText = FindLabelText(contentfulContent.content_entries)
  const staticSignupSteps: Document | null = FindStaticSteps(contentfulContent.content_entries)

  return (
    <ThemeProvider colorMode={'dark'} className={css.container}>
      {labelText ? (
        <Label color="purple" size="small" className="mb-2">
          {labelText}
        </Label>
      ) : null}
      <Heading as="h2" size="5" weight="semibold" className="mb-1">
        {title}
      </Heading>
      <ContentfulContentBlock text={text} bulletStyle={bulletStyle} />
      {staticSignupSteps ? <StaticSignupSteps content={staticSignupSteps} isLoggedIn={isLoggedIn} /> : null}
      {termsAndConditionsSubtext ? <ContentfulContentBlock text={termsAndConditionsSubtext} terms /> : null}
    </ThemeProvider>
  )
}
